package com.library.statistics; import com.library.common.Result; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/statistics") @RequiredArgsConstructor public class StatisticsController{private final JdbcTemplate jdbc;
@GetMapping("/dashboard")public Result<Map<String,Object>>dashboard(){Map<String,Object>d=new LinkedHashMap<>();d.put("bookCount",count("SELECT COUNT(*) FROM book WHERE deleted=0"));d.put("copyCount",count("SELECT COUNT(*) FROM book_copy WHERE deleted=0"));d.put("borrowedCount",count("SELECT COUNT(*) FROM borrow_record WHERE status='BORROWED'"));d.put("readerCount",count("SELECT COUNT(*) FROM reader WHERE deleted=0"));d.put("overdueCount",count("SELECT COUNT(*) FROM borrow_record WHERE status='BORROWED' AND due_time<NOW()"));d.put("reservationCount",count("SELECT COUNT(*) FROM reservation WHERE status='WAITING'"));d.put("categoryData",jdbc.queryForList("SELECT c.name,COUNT(b.id) value FROM book_category c LEFT JOIN book b ON b.category_id=c.id AND b.deleted=0 WHERE c.deleted=0 GROUP BY c.id,c.name ORDER BY value DESC"));d.put("hotBooks",jdbc.queryForList("SELECT title,borrow_count value FROM book WHERE deleted=0 ORDER BY borrow_count DESC LIMIT 6"));d.put("borrowTrend",jdbc.queryForList("SELECT DATE_FORMAT(days.d,'%m-%d') label,COALESCE(COUNT(br.id),0) value FROM (SELECT CURDATE() d UNION ALL SELECT CURDATE()-INTERVAL 1 DAY UNION ALL SELECT CURDATE()-INTERVAL 2 DAY UNION ALL SELECT CURDATE()-INTERVAL 3 DAY UNION ALL SELECT CURDATE()-INTERVAL 4 DAY UNION ALL SELECT CURDATE()-INTERVAL 5 DAY UNION ALL SELECT CURDATE()-INTERVAL 6 DAY) days LEFT JOIN borrow_record br ON DATE(br.borrow_time)=days.d GROUP BY days.d ORDER BY days.d"));return Result.ok(d);}private Long count(String sql){return jdbc.queryForObject(sql,Long.class);}}
